import { Meta, StoryObj } from "@storybook/react";
import { expect, userEvent, waitFor, within } from "storybook/test";
import { RichText, RichTextType } from "./rich-text";
import { ExistingThemes } from "@/core/types";
import { ShowcaseLayout, Variant, argTypesComponentTheme, showcaseParameters } from "@/storybook/preview";

// Small builders for Contentful rich text documents, so the stories stay readable.
const text = (value: string, marks: Array<{ type: string }> = []) => ({ nodeType: "text", value, marks, data: {} });
const block = (nodeType: string, content: Array<object>, data: object = {}) => ({ nodeType, data, content });
const paragraph = (...content: Array<object>) => block("paragraph", content);
const heading = (level: 1 | 2 | 3, value: string) => block(`heading-${level}`, [text(value)]);
const document = (...content: Array<object>) => JSON.stringify({ nodeType: "document", data: {}, content });
const entryLink = (id: string) => ({ target: { sys: { id, type: "Link", linkType: "Entry" } } });
const assetLink = (id: string) => ({ target: { sys: { id, type: "Link", linkType: "Asset" } } });

/** A document that exercises headings, marks, lists, links and embedded entries/assets. */
const fullDocument: RichTextType = {
  raw: document(
    heading(3, "Utsålt!"),
    paragraph(
      text("Här är lite "),
      text("fet", [{ type: "bold" }]),
      text(", "),
      text("kursiv", [{ type: "italic" }]),
      text(" och "),
      text("understruken", [{ type: "underline" }]),
      text(" brödtext."),
    ),
    block("unordered-list", [
      block("list-item", [paragraph(text("Första punkten"))]),
      block("list-item", [paragraph(text("Andra punkten"))]),
    ]),
    paragraph(
      text("Inline hyperlink: "),
      block("entry-hyperlink", [text("Denna länk lägger sig inuti texten")], entryLink("7fhljo8igCWgLCuIHy72Wb")),
      text(", och det är ju bra! "),
      block("asset-hyperlink", [text("Vi kan även länka till en asset")], assetLink("assetId")),
      text("."),
    ),
    paragraph(
      text("En embedded inline-länk kan ligga mitt i en rad "),
      block("embedded-entry-inline", [], entryLink("4vIE2FXYpNQPaI0cnbdT8y")),
      text(" och vi kan även länka till en Content Page: "),
      block("embedded-entry-inline", [], entryLink("contentPageId")),
    ),
    block("embedded-entry-block", [], entryLink("52nUmTBbx7o9IqJtX30U4d")),
    paragraph(text("Embedded asset (endast bild):")),
    block("embedded-asset-block", [], assetLink("assetId")),
  ),
  references: [
    {
      __typename: "ContentfulLink",
      contentful_id: "52nUmTBbx7o9IqJtX30U4d",
      title: "Köp här!",
      externalUrl: "https://gronalund.com/biljetter/grona-kortet-flow",
    },
    {
      __typename: "ContentfulLink",
      contentful_id: "7fhljo8igCWgLCuIHy72Wb",
      title: "Mat & dryck",
      externalUrl: "https://gronalund.com/mat-dryck",
    },
    {
      __typename: "ContentfulLink",
      contentful_id: "4vIE2FXYpNQPaI0cnbdT8y",
      title: "Landningssidan",
      externalUrl: "https://gronalund.com/",
    },
    {
      __typename: "ContentfulContentPage",
      contentful_id: "contentPageId",
      title: "En sida med en slug",
      slug: "/page-med-en-slug",
    },
    {
      __typename: "ContentfulAsset",
      contentful_id: "assetId",
      title: "En fin bild",
      file: {
        contentType: "image/svg+xml",
        url: "https://parksandresorts.com/assets/themes/parksandresorts/resources/images/par_logo.svg",
      },
    },
  ],
};

const shortDocument: RichTextType = {
  raw: document(
    heading(3, "Rubrik"),
    paragraph(text("Brödtext med en "), text("fet", [{ type: "bold" }]), text(" del.")),
  ),
};

const meta = {
  title: "Primitives/Rich Text",
  component: RichText,
  parameters: {
    docs: {
      description: {
        component:
          "Renders a Contentful rich text field (the `raw` JSON document plus its `references`) as styled " +
          "HTML: headings, paragraphs, lists, quotes and marks, hyperlinks, links to referenced entries and " +
          'assets, embedded images, embedded link entries as full-width buttons, and the "Expandable Text" ' +
          "rich text feature as an expand/collapse section. Text nodes can contain `{0}`-style placeholders " +
          "that are filled from `replacementArgs`.",
      },
    },
  },
  argTypes: argTypesComponentTheme,
  args: {
    richText: fullDocument,
    replacementArgs: undefined,
    componentTheme: undefined,
  },
} satisfies Meta<typeof RichText>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole("link", { name: "Köp här!" })).toHaveAttribute(
      "href",
      "https://gronalund.com/biljetter/grona-kortet-flow",
    );
    await expect(canvas.getByRole("img", { name: "En fin bild" })).toBeVisible();
  },
};

const showcaseThemes = ["winter-wonderland", "gold", "halloween"] satisfies Array<ExistingThemes>;

export const VariantComponentTheme: Story = {
  parameters: showcaseParameters,
  args: {
    richText: shortDocument,
  },
  render: (args) => (
    <ShowcaseLayout title="componentTheme" variantType="theme">
      <Variant label="undefined">
        <RichText {...args} componentTheme={undefined} />
      </Variant>
      {showcaseThemes.map((componentTheme) => (
        <Variant key={componentTheme} label={componentTheme}>
          <RichText {...args} componentTheme={componentTheme} />
        </Variant>
      ))}
    </ShowcaseLayout>
  ),
};

/** Text nodes with `{0}`, `{1}` placeholders filled from `replacementArgs`. */
export const ReplacementArgs: Story = {
  args: {
    richText: {
      raw: document(paragraph(text("Klockan {0} spelar {1} på {2}. En del attraktioner kan påverkas av detta."))),
    },
    replacementArgs: ["10:00", "Markoolio", "Stora Scen"],
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByText("Klockan 10:00 spelar Markoolio på Stora Scen.", { exact: false })).toBeVisible();
  },
};

/** The "Expandable Text" rich text feature renders its body inside an ExpandContent. */
export const ExpandableText: Story = {
  args: {
    richText: {
      raw: document(
        paragraph(text("Texten nedan är hopfälld tills besökaren klickar på Läs mer.")),
        block("embedded-entry-block", [], {
          target: {
            __typename: "ContentfulRichTextFeature",
            featureType: "Expandable Text",
            expandTextBody: {
              raw: document(paragraph(text("Här är den dolda texten som visas när sektionen fälls ut."))),
            },
          },
        }),
      ),
    },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByTestId("expand-content-toggle-button-collapsed"));
    await waitFor(() => expect(canvas.getByTestId("expand-content-toggle-button-expanded")).toBeVisible());
  },
};
